assert PT.keys() == EN.keys()
for lang, T, X in (('pt-BR', PT, EXTRA_PT), ('en', EN, EXTRA_EN)):
    p = ROOT / f'{lang}.json'
    d = json.loads(p.read_text())
    for rule, (title, body) in T.items():
        for part, txt in (('title', title), ('body', body)):
            assert '·' not in txt and '—' not in txt and 'lombo' not in txt, (rule, txt)
            d[f'advice.{rule}.{part}'] = txt
    d.update(X)
    p.write_text(json.dumps(dict(sorted(d.items())), ensure_ascii=False, indent=1) + '\n')
print('advice rules:', len(PT))
